INSERT OR IGNORE INTO [_emdash_widgets] ([id],[area_id],[sort_order],[type],[title],[content],[menu_name],[component_id],[component_props],[created_at]) VALUES ('01KQKQMCGJPRBK555K6FCR470W','01KQJ0K2J2W8AE3R790X6YZ1SF',0,'content','About Commonwealth Audiology','[{"_type":"block","style":"normal","children":[{"_type":"span","text":"Compassionate hearing care in Georgetown, KY. We are dedicated to helping you hear every meaningful moment of life."}]}]',NULL,NULL,NULL,'2026-05-02 06:57:18');
INSERT OR IGNORE INTO [_plugin_storage] ([plugin_id],[collection],[id],[data],[created_at],[updated_at]) VALUES ('audit-log','entries','1777705429588-01KQJ3519HZEF5HSZPCHZ3JTX5','{"timestamp":"2026-05-02T07:03:49.588Z","action":"delete","collection":"posts","resourceId":"01KQJ3519HZEF5HSZPCHZ3JTX5","resourceType":"content","changes":{"before":{"id":"01KQJ3519HZEF5HSZPCHZ3JTX5","type":"posts","slug":"signs-you-need-hearing-test","status":"published","data":{"title":"5 Signs You May Need a Hearing Test","content":[{"_type":"block","style":"normal","children":[{"_type":"span","text":"Hearing loss often develops so gradually that many people don''t notice it until it begins significantly affecting their daily life. Knowing the warning signs can help you seek care before the problem worsens."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"1. Asking people to repeat themselves"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"If you frequently ask friends, family, or coworkers to repeat what they''ve said, this is one of the most common early signs of hearing loss. It may be happening more than you realize."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"2. Difficulty hearing in noisy environments"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"Struggling to follow conversations in restaurants, social gatherings, or other noisy places is a hallmark sign of hearing difficulty. Background noise can be especially challenging for people with hearing loss."}]}],"excerpt":"Hearing loss often develops gradually. Here are the key signs to watch for and when to schedule your evaluation."},"createdAt":"2026-05-01T15:40:09.393Z","updatedAt":"2026-05-01T15:40:09.444Z","locale":"en","publishedAt":"2026-05-01T15:40:09.393Z","seo":{"title":null,"description":null,"image":null,"canonical":null,"noIndex":false}}}}','2026-05-02T07:03:49.588Z','2026-05-02T07:03:49.588Z');
INSERT OR IGNORE INTO [_plugin_storage] ([plugin_id],[collection],[id],[data],[created_at],[updated_at]) VALUES ('audit-log','entries','1777705433265-01KQJ0K2DANMD6AHA1S0HPM47E','{"timestamp":"2026-05-02T07:03:53.265Z","action":"delete","collection":"posts","resourceId":"01KQJ0K2DANMD6AHA1S0HPM47E","resourceType":"content","changes":{"before":{"id":"01KQJ0K2DANMD6AHA1S0HPM47E","type":"posts","slug":"building-for-the-long-term","status":"published","data":{"title":"Building for the Long Term","featured_image":{"provider":"local","id":"01KQJ0K2BBQBVR1Q58T8J1D920","alt":"Code on a monitor in a dark room","width":1200,"height":800,"mimeType":"image/jpeg","filename":"building-long-term.jpg","meta":{"storageKey":"01KQJ0K2BBQBVR1Q58T8J1D920.jpg"}},"content":[{"_type":"block","style":"normal","children":[{"_type":"span","text":"Every few years the industry collectively decides that everything we''ve been doing is wrong and there''s a better way. New frameworks, new paradigms, new build tools. The churn is relentless, and if you''re not careful, you spend more time migrating than building."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"I''ve been writing software long enough to have seen several of these cycles. jQuery to Backbone to Angular to React to whatever comes next. Each transition felt urgent at the time. Looking back, the things that actually mattered were rarely about the framework."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"What survives"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"Clean data models survive. Clear boundaries between systems survive. Good naming survives. The decision to keep things simple when you could have made them clever - that definitely survives."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"What doesn''t survive is code that was written to impress, abstractions built for problems that never materialized, and architectures designed around a framework''s opinions rather than the domain''s reality."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"The best code I''ve written is boring. It reads like prose, does one thing well, and doesn''t require a PhD in category theory to understand. The worst code I''ve written was technically impressive at the time."}]}],"excerpt":"The frameworks will change. The databases will change. What survives is the clarity of your thinking."},"createdAt":"2026-05-01T14:55:23.563Z","updatedAt":"2026-05-01T14:55:23.563Z","locale":"en","publishedAt":"2026-05-01T14:55:23.562Z","seo":{"title":null,"description":null,"image":null,"canonical":null,"noIndex":false}}}}','2026-05-02T07:03:53.265Z','2026-05-02T07:03:53.265Z');
INSERT OR IGNORE INTO [_plugin_storage] ([plugin_id],[collection],[id],[data],[created_at],[updated_at]) VALUES ('audit-log','entries','1777705454362-01KQJ0K2E84HJ5GWN8YTDTMRAP','{"timestamp":"2026-05-02T07:04:14.362Z","action":"delete","collection":"posts","resourceId":"01KQJ0K2E84HJ5GWN8YTDTMRAP","resourceType":"content","changes":{"before":{"id":"01KQJ0K2E84HJ5GWN8YTDTMRAP","type":"posts","slug":"the-case-for-static","status":"published","data":{"title":"The Case for Static","featured_image":{"provider":"local","id":"01KQJ0K2DVD57NXVC911HWR3P7","alt":"Laptop and coffee on a wooden table","width":1200,"height":800,"mimeType":"image/jpeg","filename":"case-for-static.jpg","meta":{"storageKey":"01KQJ0K2DVD57NXVC911HWR3P7.jpg"}},"content":[{"_type":"block","style":"normal","children":[{"_type":"span","text":"There''s a certain irony in the fact that the web started static, went dynamic, and is now swinging back toward static again. But the static sites of today aren''t the hand-coded HTML pages of 1998. They''re generated, optimized, and deployed to edge networks that serve them in milliseconds."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"The pitch for server-rendered everything was compelling: dynamic content, personalization, real-time data. But most sites don''t need most of that most of the time. A blog post doesn''t need to be rendered on every request. A product page doesn''t change every second."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"The performance argument"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"A static file served from a CDN is as fast as the web gets. No cold starts, no database queries, no server-side rendering overhead. The Time to First Byte is essentially the network latency to your nearest edge node. You can''t beat physics."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"And when you do need dynamic behavior, you can add it surgically. An island of interactivity in a sea of static HTML. The best of both worlds, without paying the cost of either at all times."}]}],"excerpt":"Static sites aren''t a step backwards. They''re what you get when you take performance and simplicity seriously."},"createdAt":"2026-05-01T14:55:23.592Z","updatedAt":"2026-05-01T14:55:23.592Z","locale":"en","publishedAt":"2026-05-01T14:55:23.592Z","seo":{"title":null,"description":null,"image":null,"canonical":null,"noIndex":false}}}}','2026-05-02T07:04:14.362Z','2026-05-02T07:04:14.362Z');
INSERT OR IGNORE INTO [_plugin_storage] ([plugin_id],[collection],[id],[data],[created_at],[updated_at]) VALUES ('audit-log','entries','1777705456441-01KQJ0K2F20HRP7V5X7DCVWBX2','{"timestamp":"2026-05-02T07:04:16.441Z","action":"delete","collection":"posts","resourceId":"01KQJ0K2F20HRP7V5X7DCVWBX2","resourceType":"content","changes":{"before":{"id":"01KQJ0K2F20HRP7V5X7DCVWBX2","type":"posts","slug":"learning-in-public","status":"published","data":{"title":"Learning in Public","featured_image":{"provider":"local","id":"01KQJ0K2EPKF8ZZKAVNF2ZP31P","alt":"Notebook and pen on a desk","width":1200,"height":800,"mimeType":"image/jpeg","filename":"learning-in-public.jpg","meta":{"storageKey":"01KQJ0K2EPKF8ZZKAVNF2ZP31P.jpg"}},"content":[{"_type":"block","style":"normal","children":[{"_type":"span","text":"I started writing about things I was learning not because I had anything original to say, but because I kept forgetting what I''d figured out. The blog posts were notes to my future self, published publicly more out of laziness than courage."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"What I didn''t expect was how much the writing itself would accelerate the learning. There''s a particular kind of clarity that comes from trying to explain something to someone else. The gaps in your understanding, which you can happily ignore when the knowledge lives only in your head, become painfully obvious when you try to put it into sentences."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"The fear of being wrong"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"The biggest barrier isn''t time or writing skill. It''s the fear of publishing something that turns out to be wrong. But here''s the thing: being wrong publicly is one of the most efficient ways to learn. Someone will correct you, often kindly, and you''ll remember that correction forever."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"The posts that helped me most weren''t written by experts. They were written by people one step ahead of me on the same path, in language that hadn''t yet been polished into abstraction. There''s a place for that kind of writing, and it''s more valuable than most people realize."}]}],"excerpt":"Writing about what you''re learning is the fastest way to find out what you don''t actually understand."},"createdAt":"2026-05-01T14:55:23.619Z","updatedAt":"2026-05-01T14:55:23.619Z","locale":"en","publishedAt":"2026-05-01T14:55:23.618Z","seo":{"title":null,"description":null,"image":null,"canonical":null,"noIndex":false}}}}','2026-05-02T07:04:16.441Z','2026-05-02T07:04:16.441Z');
INSERT OR IGNORE INTO [_plugin_storage] ([plugin_id],[collection],[id],[data],[created_at],[updated_at]) VALUES ('audit-log','entries','1777705458345-01KQJ0K2FN006K7KZ5G84JXGZ1','{"timestamp":"2026-05-02T07:04:18.345Z","action":"delete","collection":"posts","resourceId":"01KQJ0K2FN006K7KZ5G84JXGZ1","resourceType":"content","changes":{"before":{"id":"01KQJ0K2FN006K7KZ5G84JXGZ1","type":"posts","slug":"small-tools-big-impact","status":"published","data":{"title":"Small Tools, Big Impact","featured_image":{"provider":"local","id":"01KQJ0K2FHEX96H1Y4XFBPY83H","alt":"Wrenches and hand tools hanging on a workshop wall","width":1200,"height":800,"mimeType":"image/jpeg","filename":"small-tools.jpg","meta":{"storageKey":"01KQJ0K2FHEX96H1Y4XFBPY83H.jpg"}},"content":[{"_type":"block","style":"normal","children":[{"_type":"span","text":"There''s a class of software that doesn''t get enough appreciation. Not the frameworks or the platforms or the IDEs, but the small, sharp tools that solve one problem so well you stop thinking about them. They become invisible, which is the highest compliment you can pay a tool."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"I''m talking about things like ripgrep, which searches code so fast it changed how I think about searching. Or jq, which makes JSON feel like a first-class data format in the terminal. Or curl, which has been quietly powering the internet''s plumbing for decades."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"The Unix philosophy, revisited"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"Do one thing well. The advice is old enough to be a cliche, but the best modern tools still follow it. They don''t try to be platforms. They don''t have plugin ecosystems or configuration languages or startup wizards. They do their job and they compose with other tools that do theirs."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"The temptation is always to add more. One more feature, one more option, one more integration. But every addition is a decision someone has to make, a path through the code that has to be maintained, a thing that can break. The best tools resist this. They stay small, and in staying small, they stay reliable."}]}],"excerpt":"The best developer tools do one thing well and get out of your way. A love letter to focused software."},"createdAt":"2026-05-01T14:55:23.637Z","updatedAt":"2026-05-01T14:55:23.637Z","locale":"en","publishedAt":"2026-05-01T14:55:23.637Z","seo":{"title":null,"description":null,"image":null,"canonical":null,"noIndex":false}}}}','2026-05-02T07:04:18.345Z','2026-05-02T07:04:18.345Z');
INSERT OR IGNORE INTO [_plugin_storage] ([plugin_id],[collection],[id],[data],[created_at],[updated_at]) VALUES ('audit-log','entries','1777705461454-01KQJ0K2GE41V53BEVYNRRZ2ZZ','{"timestamp":"2026-05-02T07:04:21.454Z","action":"delete","collection":"posts","resourceId":"01KQJ0K2GE41V53BEVYNRRZ2ZZ","resourceType":"content","changes":{"before":{"id":"01KQJ0K2GE41V53BEVYNRRZ2ZZ","type":"posts","slug":"designing-with-constraints","status":"published","data":{"title":"Designing with Constraints","featured_image":{"provider":"local","id":"01KQJ0K2GBE0QKQZEE9NNMBMG0","alt":"Pencils and design tools on a desk","width":1200,"height":800,"mimeType":"image/jpeg","filename":"designing-with-constraints.jpg","meta":{"storageKey":"01KQJ0K2GBE0QKQZEE9NNMBMG0.jpg"}},"content":[{"_type":"block","style":"normal","children":[{"_type":"span","text":"Give a designer a blank canvas and unlimited time, and they''ll often produce something mediocre. Give them a tight brief, a small screen, and a deadline, and they''ll surprise you. This isn''t a paradox - it''s how creativity actually works."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"Constraints force decisions. When you can''t use more than two typefaces, you have to choose carefully. When the page has to load in under a second, every element earns its place. When the interface has to work on a 320px screen, you discover what''s truly essential."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"Embracing the box"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"The web itself is a constraint. HTML flows in one direction. CSS has a box model. Browsers have viewport sizes and font rendering quirks. You can fight these constraints or you can work with them, and the results are dramatically different."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"The designs I admire most don''t look like they were forced through a framework. They look like they grew naturally from the medium, respecting its grain rather than working against it. That only happens when you treat constraints as creative partners rather than enemies."}]}],"excerpt":"Limitations aren''t obstacles to creativity. They''re the structure that makes creativity possible."},"createdAt":"2026-05-01T14:55:23.662Z","updatedAt":"2026-05-01T14:55:23.662Z","locale":"en","publishedAt":"2026-05-01T14:55:23.662Z","seo":{"title":null,"description":null,"image":null,"canonical":null,"noIndex":false}}}}','2026-05-02T07:04:21.454Z','2026-05-02T07:04:21.454Z');
INSERT OR IGNORE INTO [_plugin_storage] ([plugin_id],[collection],[id],[data],[created_at],[updated_at]) VALUES ('audit-log','entries','1777705463849-01KQJ0K2H8V8FZ6C7E99H8M9QT','{"timestamp":"2026-05-02T07:04:23.849Z","action":"delete","collection":"posts","resourceId":"01KQJ0K2H8V8FZ6C7E99H8M9QT","resourceType":"content","changes":{"before":{"id":"01KQJ0K2H8V8FZ6C7E99H8M9QT","type":"posts","slug":"a-weekend-with-a-side-project","status":"published","data":{"title":"A Weekend with a Side Project","featured_image":{"provider":"local","id":"01KQJ0K2H51K4VN6R2EWYJZ459","alt":"Code on a screen with a dark theme","width":1200,"height":800,"mimeType":"image/jpeg","filename":"weekend-side-project.jpg","meta":{"storageKey":"01KQJ0K2H51K4VN6R2EWYJZ459.jpg"}},"content":[{"_type":"block","style":"normal","children":[{"_type":"span","text":"Saturday morning. Coffee''s made, the house is quiet, and I''ve got an idea that''s been nagging at me all week. Not a good idea, necessarily - just a persistent one. A small tool that does a thing I keep doing manually. How hard could it be?"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"This is the best kind of programming. No requirements document, no sprint planning, no pull request reviews. Just a text editor and a problem. The freedom to make terrible architectural decisions, rewrite everything twice, and follow tangents that turn out to be dead ends."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"Why side projects matter"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"Side projects are where you learn things your day job would never teach you. Not because the problems are harder, but because you''re free to take risks. Try a language you''ve never used. Build something without a framework. Deploy to a platform you''ve only read about. The stakes are zero, which makes the learning maximum."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"By Sunday evening, the thing sort of works. It''s rough, the error handling is nonexistent, and the README is a single sentence. But it solves the problem I set out to solve, and I learned three things I didn''t know on Friday. Not a bad weekend."}]}],"excerpt":"No stakeholders, no deadlines, no Jira tickets. Just you and a dumb idea that might turn into something."},"createdAt":"2026-05-01T14:55:23.688Z","updatedAt":"2026-05-01T14:55:23.688Z","locale":"en","publishedAt":"2026-05-01T14:55:23.688Z","seo":{"title":null,"description":null,"image":null,"canonical":null,"noIndex":false}}}}','2026-05-02T07:04:23.849Z','2026-05-02T07:04:23.849Z');
INSERT OR IGNORE INTO [_plugin_storage] ([plugin_id],[collection],[id],[data],[created_at],[updated_at]) VALUES ('audit-log','entries','1777705465514-01KQJ0K2HX6NQHE6H6WN2MMYKV','{"timestamp":"2026-05-02T07:04:25.514Z","action":"delete","collection":"posts","resourceId":"01KQJ0K2HX6NQHE6H6WN2MMYKV","resourceType":"content","changes":{"before":{"id":"01KQJ0K2HX6NQHE6H6WN2MMYKV","type":"posts","slug":"notes-on-simplicity","status":"published","data":{"title":"Notes on Simplicity","featured_image":{"provider":"local","id":"01KQJ0K2HQ7MBS53W319M1Y2V4","alt":"Geometric pattern carved into white paper","width":1200,"height":800,"mimeType":"image/jpeg","filename":"notes-on-simplicity.jpg","meta":{"storageKey":"01KQJ0K2HQ7MBS53W319M1Y2V4.jpg"}},"content":[{"_type":"block","style":"normal","children":[{"_type":"span","text":"Every piece of software starts simple. A few files, a clear purpose, a small surface area. Then features get added, edge cases get handled, and before long you''re looking at something that requires a diagram to understand. This isn''t inevitable, but it takes discipline to prevent."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"The hard part of simplicity isn''t the initial design. It''s the ongoing resistance to complication. Every feature request, every bug fix, every refactor is an opportunity to add complexity. Saying no is the most important design skill, and the least celebrated."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"Removing as a feature"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"The best version of a product often has fewer features than the previous one. Not because features were missing, but because someone had the courage to remove things that weren''t earning their keep. Every feature has a cost - in maintenance, in cognitive load, in the weight of the interface."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"Simplicity is a practice, not a destination. You never arrive at simple. You just keep asking: is this necessary? Could this be clearer? Is there a way to solve this problem by removing something instead of adding something? The answer is yes more often than you''d expect."}]}],"excerpt":"Simplicity isn''t the absence of complexity. It''s the result of understanding a problem well enough to solve it cleanly."},"createdAt":"2026-05-01T14:55:23.709Z","updatedAt":"2026-05-01T14:55:23.709Z","locale":"en","publishedAt":"2026-05-01T14:55:23.709Z","seo":{"title":null,"description":null,"image":null,"canonical":null,"noIndex":false}}}}','2026-05-02T07:04:25.514Z','2026-05-02T07:04:25.514Z');
INSERT OR IGNORE INTO [_plugin_storage] ([plugin_id],[collection],[id],[data],[created_at],[updated_at]) VALUES ('audit-log','entries','1777705467505-01KQJ0K2HYHX790DAN86FS3MKZ','{"timestamp":"2026-05-02T07:04:27.504Z","action":"delete","collection":"posts","resourceId":"01KQJ0K2HYHX790DAN86FS3MKZ","resourceType":"content","changes":{"before":{"id":"01KQJ0K2HYHX790DAN86FS3MKZ","type":"posts","slug":"work-in-progress","status":"draft","data":{"title":"Work in Progress","content":[{"_type":"block","style":"normal","children":[{"_type":"span","text":"This is a draft post that won''t appear in the public listing."}]}],"excerpt":"This post is still being written."},"createdAt":"2026-05-01T14:55:23.711Z","updatedAt":"2026-05-01T14:55:23.711Z","locale":"en","publishedAt":null,"seo":{"title":null,"description":null,"image":null,"canonical":null,"noIndex":false}}}}','2026-05-02T07:04:27.505Z','2026-05-02T07:04:27.505Z');
