INSERT OR IGNORE INTO [credentials] ([id],[user_id],[public_key],[counter],[device_type],[backed_up],[transports],[name],[created_at],[last_used_at]) VALUES ('FfSzQzgltyr3z_WuCS5MRPXRDXiv_-zICt-sbn5ynKQ','01KQKQN697CTSD9ZXEY20B5GA1',X'041ac01adc70bdd15f982bc0e32dfaf85bbdadcec6c660ff7764623326935e61aab5513bb9a5c994596e955b5510ed17c7349ccb0e9695065198b5e3d81f473968',1,'singleDevice',0,'["internal"]','Setup passkey','2026-05-02T06:57:44.766Z','2026-05-02T07:00:14.242Z');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350GM4HA1TJH2YK9A8ATG','site_config','01KQJ350GK9DQHMZYC30M6ZM54','{"phone":"(844) 442-4222","address_line1":"201 Believe Lane, Suite B","address_line2":"","city_state":"Georgetown, KY 40324","email":"info@commonwealthaudiology.com","book_url":"#book","hero_heading":"Compassionate hearing care that feels like home.","hero_subtext":"Hearing care you can trust, for every stage of life.","about_tagline":"AUDIOLOGY EXCELLENCE & PATIENT CARE","about_heading":"Commonwealth Audiology","about_text":"Life is full of meaningful sounds: laughter with loved ones, conversations with friends, music you love, and the world sounds all around you. When this changes, it can feel isolating, but we''re here to help. At Commonwealth Audiology, your hearing wellness is our top priority. Every recommendation we make is shaped by what functions for your specific lifestyle needs and the life you love to live. Our Doctor of Audiology, Dr. Tiffany Brown, stays up to date with the latest hearing technology to ensure you receive the most effective and innovative care available.","team_heading":"Meet Your Local Hearing Professionals","team_text":"At Commonwealth Audiology, our focus is on restoring clarity, comfort, and confidence so you can fully participate in the world around you. With superior guidance, clinical excellence, and care centered on you, we partner with our patients and their families each and every day.","hours_mon":"9:00am - 5:00pm","hours_tue":"9:00am - 5:00pm","hours_wed":"9:00am - 5:00pm","hours_thu":"9:00am - 5:00pm","hours_fri":"9:00am - 5:00pm","hours_sat":"9:00am - 1:00pm","hours_sun":"Closed","map_embed_url":"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3134!2d-84.5603!3d38.2098!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x0!2zMzjCsDEyJzM1LjMiTiA4NMKwMzMnMzcuMSJX!5e0!3m2!1sen!2sus!4v1234567890","services_heading":"Audiology Services in Georgetown, KY","services_subtext":"At Commonwealth Audiology, we provide hearing care to meet your every need. It''s our commitment to make sure you can hear every moment clearly.","hearing_aids_heading":"Hearing Aids & Hearing Aid Services","hearing_aids_subtext":"We provide best-in-class hearing aid solutions with expert fittings, adjustments, repairs, and ongoing maintenance so you can hear your best every day.","protection_heading":"Hearing Protection Solutions in Georgetown, KY","protection_subtext":"For anyone exposed to loud noise, custom ear protection offers the safest and most comfortable way to preserve your hearing.","testimonials_heading":"What Our Patients Are Saying","faq_heading":"Frequently Asked Questions","news_heading":"News & Articles","footer_tagline":"Compassionate hearing care in Georgetown, KY. Helping you hear every meaningful moment of life."}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350GQ3WPEY0TR76AVKQPD','services','01KQJ350GPSVZ2Y02YX71CDAMJ','{"title":"Hearing Evaluations","description":"A comprehensive hearing evaluation is the first step toward better hearing. Our Doctor of Audiology will assess your hearing health using the latest diagnostic tools and techniques.","link_url":"/services","sort_order":"1"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350GRSMA0MV8VEQYF5WQM','services','01KQJ350GR4MVYAX0Y2RQ0HJE3','{"title":"Hearing Loss Evaluation & Treatment","description":"We work together to understand what you are experiencing and recommend treatment options tailored to your specific type and degree of hearing loss with confidence.","link_url":"/services","sort_order":"2"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350GT87J4PTFED13MZRHF','services','01KQJ350GS985T25ZZ6TJ8G6Q7','{"title":"Ear Wax Removal","description":"Excess earwax can sometimes accumulate and cause hearing loss. Our safe, professional ear wax removal services restore your hearing clarity quickly and comfortably.","link_url":"/services","sort_order":"3"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350GVAA7K3F45DG6D3QEA','services','01KQJ350GV7VZ9S4ZW94JDGBK1','{"title":"Tinnitus Evaluations & Treatment","description":"Ringing, buzzing, or whooshing in the ears can be stressful. We fully evaluate your tinnitus and discuss various treatment options designed to find what works best for you.","link_url":"/services","sort_order":"4"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350GXZ91N19HPDA794VCQ','hearing_aids','01KQJ350GW1J67QJZ2E062V0XW','{"title":"Hearing Aid Selection","description":"We offer a full line of hearing aid styles, including completely-in-canal and Bluetooth-compatible models, allowing you to select the style that fits your budget, lifestyle, and hearing needs.","link_url":"/hearing-aids","sort_order":"1"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350GZSNANQRXGA1HK5P2C','hearing_aids','01KQJ350GYXDZ07YTKK01D3E22','{"title":"Hearing Aid Fittings","description":"We take great care with precise new adjustments, using real-ear measurement to ensure you can be confident and comfortable with your hearing aids in any situation.","link_url":"/hearing-aids","sort_order":"2"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350H1B1P3CJSHG6EA0WZK','hearing_aids','01KQJ350H1ZSJ2A4H58ZPDEDFM','{"title":"Hearing Aid Cleaning & Repair","description":"We provide cleaning, troubleshooting, and simple repairs so your devices work as comfortably and as well as the day you received them, getting you back to better hearing fast.","link_url":"/hearing-aids","sort_order":"3"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350H2B66QX9DRCJ7YT6BW','hearing_aids','01KQJ350H2CT08E87SRG54Z1HF','{"title":"Hearing Aid Batteries & Accessories","description":"We carry a variety of batteries, chargers, cleaning tools, and accessories to keep your hearing devices running and sounding their very best.","link_url":"/hearing-aids","sort_order":"4"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350H43Q0HHVCPC72387KM','team','01KQJ350H38VYE68HDVQMPFQRA','{"name":"Dr. Tiffany Brown","role":"Doctor of Audiology","bio":"Dr. Tiffany Brown is committed to providing personalized, compassionate hearing care to every patient.","sort_order":"1"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350H97B0JT038ZJ4GGSG6','team','01KQJ350H583D6ED33X0R8CRZ3','{"name":"Ashley Gogols","role":"Hearing Instrument Specialist","bio":"Ashley is dedicated to helping patients find the right hearing solutions for their unique lifestyle.","sort_order":"2"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350HAW7BHNKMVY6A2VBSB','testimonials','01KQJ350HAHBR7HKBPGNEW79M2','{"patient_name":"Laci Wills","rating":"5","review":"Absolutely love this place! The staff is so friendly and helpful. My hearing aids have changed my life and I couldn''t be more grateful!","sort_order":"1"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350HC6WRYF0J03Z36D1ZB','testimonials','01KQJ350HBFBJNC7NBZNZ4Q3YF','{"patient_name":"Tracy Davis","rating":"5","review":"Professional, knowledgeable, and kind. The whole team made me feel comfortable from the moment I walked in. Highly recommend Commonwealth Audiology!","sort_order":"2"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350HD4F01GQTJZFQNPQHJ','testimonials','01KQJ350HD10YKTSJZ8A45ZC47','{"patient_name":"Ola Mack","rating":"5","review":"Great experience from start to finish. Dr. Brown took the time to really listen and find the perfect solution for me. Outstanding care!","sort_order":"3"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350HEB2XV79ANQJT9NT9A','testimonials','01KQJ350HEV9BXAWTYYZY5ZR4W','{"patient_name":"Garrett Hanover","rating":"5","review":"I was nervous about getting hearing aids, but the team here made the whole process easy and stress-free. Amazing patient care!","sort_order":"4"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350HF2D69NQ2MJF7V0CB9','testimonials','01KQJ350HFJZ9T3RQ8V5XKPBPZ','{"patient_name":"Audra Rugg","rating":"5","review":"Commonwealth Audiology exceeded all my expectations. The care is professional, the staff are wonderful, and I can finally hear again!","sort_order":"5"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350HH5MP01DAHDHVPMBX0','faq','01KQJ350HGFVSCGTZFGHJ3ZD0K','{"question":"How do I know if I need a hearing aid?","answer":"If you frequently ask people to repeat themselves, have difficulty hearing in noisy environments, or find yourself turning up the TV volume, it may be time for a hearing evaluation. Schedule an appointment with our audiologist for a comprehensive assessment.","sort_order":"1"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350SJ0RYC6J10BVY1N9F8','faq','01KQJ350SGN0CFQT32TY919VB0','{"question":"Are hearing aids covered by insurance?","answer":"Coverage varies by insurance plan. Many plans offer partial coverage for hearing aids. Our team can help you understand your benefits and explore financing options to make hearing care accessible for you.","sort_order":"2"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350VBGH6BJV5W9AHPGRJP','faq','01KQJ350V7TTJK0FDBNMKDC3X9','{"question":"How often should I get a hearing test?","answer":"Adults should have their hearing tested every 3-5 years, or more frequently if you notice changes. Those with existing hearing loss or high noise exposure should be tested annually.","sort_order":"3"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350VG8BTC6AY0XFQKSWFV','faq','01KQJ350VE5HBKRJVX0X3M5CRD','{"question":"Can I get a hearing aid without a fitting?","answer":"A professional fitting is essential for optimal hearing aid performance. Proper fitting ensures the device is programmed correctly for your specific hearing loss, fits comfortably, and delivers the best possible sound quality.","sort_order":"4"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350VRJH9CR0ENPSWZYBBH','faq','01KQJ350VMXP8HWAXRKNVGP06N','{"question":"How can hearing aids help with tinnitus?","answer":"Many modern hearing aids include tinnitus masking features that produce soothing sounds to reduce the perception of ringing. Combined with hearing amplification, they can significantly improve quality of life for tinnitus sufferers.","sort_order":"5"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350VZGN38642W6JGH6YQ7','hearing_protection','01KQJ350VYRQDZC2JENHFDX4ZK','{"title":"Custom Hearing Protection & Ear Molds","description":"Our custom ear solutions reduce harmful sounds while keeping important sounds audible, so you can work safely and enjoy what you love without fear of hearing damage.","sort_order":"1"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350W520JCVTA914XCKRQ7','hearing_protection','01KQJ350W3D6DX86YYR7VEQ4K7','{"title":"Hearing Protection for Musicians","description":"Musicians are at high risk for regular exposure to loud volumes that can harm their hearing. We provide specially designed protection that lets you enjoy music you love while preserving your hearing for years to come.","sort_order":"2"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350WPRVN4XB8Q4PEJ10B5','hearing_protection','01KQJ350WF2QWY106GWWZMGA4S','{"title":"Hearing Protection for Hunters","description":"Sudden, loud blasts from firearms can cause severe, permanent hearing damage. Our custom hunter''s ear protection provides incredible ambient sound awareness while protecting your hearing from dangerous impulse noise.","sort_order":"3"}',NULL,'2026-05-01 15:40:08');
