INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ350X762SWNW59GK9EAN3C','brands','01KQJ350X6AD1DYVVH9KS49VAT','{"name":"Signia","sort_order":"7"}',NULL,'2026-05-01 15:40:08');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ351B4NEVXM1Y0C6JD73X7','posts','01KQJ3519HZEF5HSZPCHZ3JTX5','{"title":"5 Signs You May Need a Hearing Test","content":[{"_type":"block","style":"normal","children":[{"_type":"span","text":"Hearing loss often develops so gradually that many people don''t notice it until it begins significantly affecting their daily life. Knowing the warning signs can help you seek care before the problem worsens."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"1. Asking people to repeat themselves"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"If you frequently ask friends, family, or coworkers to repeat what they''ve said, this is one of the most common early signs of hearing loss. It may be happening more than you realize."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"2. Difficulty hearing in noisy environments"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"Struggling to follow conversations in restaurants, social gatherings, or other noisy places is a hallmark sign of hearing difficulty. Background noise can be especially challenging for people with hearing loss."}]}],"excerpt":"Hearing loss often develops gradually. Here are the key signs to watch for and when to schedule your evaluation."}',NULL,'2026-05-01 15:40:09');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ351DVDH9AN81AF2Q8ZJ77','posts','01KQJ351DN14CXS7AKYAZSQR06','{"title":"How Modern Hearing Aid Technology Has Changed Lives","content":[{"_type":"block","style":"normal","children":[{"_type":"span","text":"The hearing aids of today bear little resemblance to the bulky, whistling devices of decades past. Modern hearing aids are sleek, nearly invisible, and packed with technology that adapts to your environment in real time."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"Bluetooth connectivity"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"Most modern hearing aids can connect directly to smartphones, TVs, and other Bluetooth devices. This means you can stream phone calls, music, and audio directly to your hearing aids."}]}],"excerpt":"Today''s hearing aids are more advanced than ever — smaller, smarter, and connected. Here''s what you need to know."}',NULL,'2026-05-01 15:40:09');
INSERT OR IGNORE INTO [revisions] ([id],[collection],[entry_id],[data],[author_id],[created_at]) VALUES ('01KQJ351G32SCDZ214VE28DK5R','posts','01KQJ351G09Z02G1N67A535JA1','{"title":"Tinnitus: Causes, Symptoms, and Treatment Options","content":[{"_type":"block","style":"normal","children":[{"_type":"span","text":"Tinnitus — the perception of ringing, buzzing, hissing, or other sounds in the ears — affects an estimated 50 million Americans. While it can be distressing, many effective management strategies are available."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"Common causes of tinnitus"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"Tinnitus can be caused by noise-induced hearing loss, age-related hearing loss, ear infections, earwax blockage, certain medications, or other medical conditions. Identifying the underlying cause is the first step to effective treatment."}]}],"excerpt":"Ringing in the ears affects millions of Americans. Learn what causes tinnitus and how it can be treated."}',NULL,'2026-05-01 15:40:09');
