INSERT OR IGNORE INTO [ec_faq] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[question],[answer],[sort_order]) VALUES ('01KQJ350HGFVSCGTZFGHJ3ZD0K','how-do-i-know-if-i-need-hearing-aid','published',NULL,NULL,'2026-05-01T15:40:08.624Z','2026-05-01T15:40:08.625Z','2026-05-01T15:40:08.624Z',NULL,NULL,1,'01KQJ350HH5MP01DAHDHVPMBX0',NULL,'en','01KQJ350HGFVSCGTZFGHJ3ZD0K','How do I know if I need a hearing aid?','If you frequently ask people to repeat themselves, have difficulty hearing in noisy environments, or find yourself turning up the TV volume, it may be time for a hearing evaluation. Schedule an appointment with our audiologist for a comprehensive assessment.','1');
INSERT OR IGNORE INTO [ec_faq] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[question],[answer],[sort_order]) VALUES ('01KQJ350SGN0CFQT32TY919VB0','are-hearing-aids-covered-by-insurance','published',NULL,NULL,'2026-05-01T15:40:08.880Z','2026-05-01T15:40:08.881Z','2026-05-01T15:40:08.880Z',NULL,NULL,1,'01KQJ350SJ0RYC6J10BVY1N9F8',NULL,'en','01KQJ350SGN0CFQT32TY919VB0','Are hearing aids covered by insurance?','Coverage varies by insurance plan. Many plans offer partial coverage for hearing aids. Our team can help you understand your benefits and explore financing options to make hearing care accessible for you.','2');
INSERT OR IGNORE INTO [ec_faq] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[question],[answer],[sort_order]) VALUES ('01KQJ350V7TTJK0FDBNMKDC3X9','how-often-should-i-get-hearing-test','published',NULL,NULL,'2026-05-01T15:40:08.935Z','2026-05-01T15:40:08.939Z','2026-05-01T15:40:08.935Z',NULL,NULL,1,'01KQJ350VBGH6BJV5W9AHPGRJP',NULL,'en','01KQJ350V7TTJK0FDBNMKDC3X9','How often should I get a hearing test?','Adults should have their hearing tested every 3-5 years, or more frequently if you notice changes. Those with existing hearing loss or high noise exposure should be tested annually.','3');
INSERT OR IGNORE INTO [ec_faq] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[question],[answer],[sort_order]) VALUES ('01KQJ350VE5HBKRJVX0X3M5CRD','can-i-get-hearing-aid-without-fitting','published',NULL,NULL,'2026-05-01T15:40:08.943Z','2026-05-01T15:40:08.944Z','2026-05-01T15:40:08.942Z',NULL,NULL,1,'01KQJ350VG8BTC6AY0XFQKSWFV',NULL,'en','01KQJ350VE5HBKRJVX0X3M5CRD','Can I get a hearing aid without a fitting?','A professional fitting is essential for optimal hearing aid performance. Proper fitting ensures the device is programmed correctly for your specific hearing loss, fits comfortably, and delivers the best possible sound quality.','4');
INSERT OR IGNORE INTO [ec_faq] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[question],[answer],[sort_order]) VALUES ('01KQJ350VMXP8HWAXRKNVGP06N','how-can-hearing-aids-help-with-tinnitus','published',NULL,NULL,'2026-05-01T15:40:08.949Z','2026-05-01T15:40:08.952Z','2026-05-01T15:40:08.948Z',NULL,NULL,1,'01KQJ350VRJH9CR0ENPSWZYBBH',NULL,'en','01KQJ350VMXP8HWAXRKNVGP06N','How can hearing aids help with tinnitus?','Many modern hearing aids include tinnitus masking features that produce soothing sounds to reduce the perception of ringing. Combined with hearing amplification, they can significantly improve quality of life for tinnitus sufferers.','5');
INSERT OR IGNORE INTO [ec_hearing_aids] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[description],[image],[link_url],[sort_order]) VALUES ('01KQJ350GW1J67QJZ2E062V0XW','hearing-aid-selection','published',NULL,NULL,'2026-05-01T15:40:08.604Z','2026-05-01T15:40:08.605Z','2026-05-01T15:40:08.604Z',NULL,NULL,1,'01KQJ350GXZ91N19HPDA794VCQ',NULL,'en','01KQJ350GW1J67QJZ2E062V0XW','Hearing Aid Selection','We offer a full line of hearing aid styles, including completely-in-canal and Bluetooth-compatible models, allowing you to select the style that fits your budget, lifestyle, and hearing needs.',NULL,'/hearing-aids','1');
INSERT OR IGNORE INTO [ec_hearing_aids] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[description],[image],[link_url],[sort_order]) VALUES ('01KQJ350GYXDZ07YTKK01D3E22','hearing-aid-fittings','published',NULL,NULL,'2026-05-01T15:40:08.606Z','2026-05-01T15:40:08.607Z','2026-05-01T15:40:08.606Z',NULL,NULL,1,'01KQJ350GZSNANQRXGA1HK5P2C',NULL,'en','01KQJ350GYXDZ07YTKK01D3E22','Hearing Aid Fittings','We take great care with precise new adjustments, using real-ear measurement to ensure you can be confident and comfortable with your hearing aids in any situation.',NULL,'/hearing-aids','2');
INSERT OR IGNORE INTO [ec_hearing_aids] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[description],[image],[link_url],[sort_order]) VALUES ('01KQJ350H1ZSJ2A4H58ZPDEDFM','hearing-aid-cleaning-repair','published',NULL,NULL,'2026-05-01T15:40:08.609Z','2026-05-01T15:40:08.609Z','2026-05-01T15:40:08.609Z',NULL,NULL,1,'01KQJ350H1B1P3CJSHG6EA0WZK',NULL,'en','01KQJ350H1ZSJ2A4H58ZPDEDFM','Hearing Aid Cleaning & Repair','We provide cleaning, troubleshooting, and simple repairs so your devices work as comfortably and as well as the day you received them, getting you back to better hearing fast.',NULL,'/hearing-aids','3');
INSERT OR IGNORE INTO [ec_hearing_aids] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[description],[image],[link_url],[sort_order]) VALUES ('01KQJ350H2CT08E87SRG54Z1HF','hearing-aid-batteries-accessories','published',NULL,NULL,'2026-05-01T15:40:08.610Z','2026-05-01T15:40:08.610Z','2026-05-01T15:40:08.610Z',NULL,NULL,1,'01KQJ350H2B66QX9DRCJ7YT6BW',NULL,'en','01KQJ350H2CT08E87SRG54Z1HF','Hearing Aid Batteries & Accessories','We carry a variety of batteries, chargers, cleaning tools, and accessories to keep your hearing devices running and sounding their very best.',NULL,'/hearing-aids','4');
INSERT OR IGNORE INTO [ec_hearing_protection] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[description],[sort_order]) VALUES ('01KQJ350VYRQDZC2JENHFDX4ZK','custom-hearing-protection','published',NULL,NULL,'2026-05-01T15:40:08.958Z','2026-05-01T15:40:08.959Z','2026-05-01T15:40:08.958Z',NULL,NULL,1,'01KQJ350VZGN38642W6JGH6YQ7',NULL,'en','01KQJ350VYRQDZC2JENHFDX4ZK','Custom Hearing Protection & Ear Molds','Our custom ear solutions reduce harmful sounds while keeping important sounds audible, so you can work safely and enjoy what you love without fear of hearing damage.','1');
INSERT OR IGNORE INTO [ec_hearing_protection] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[description],[sort_order]) VALUES ('01KQJ350W3D6DX86YYR7VEQ4K7','hearing-protection-musicians','published',NULL,NULL,'2026-05-01T15:40:08.963Z','2026-05-01T15:40:08.964Z','2026-05-01T15:40:08.963Z',NULL,NULL,1,'01KQJ350W520JCVTA914XCKRQ7',NULL,'en','01KQJ350W3D6DX86YYR7VEQ4K7','Hearing Protection for Musicians','Musicians are at high risk for regular exposure to loud volumes that can harm their hearing. We provide specially designed protection that lets you enjoy music you love while preserving your hearing for years to come.','2');
INSERT OR IGNORE INTO [ec_hearing_protection] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[description],[sort_order]) VALUES ('01KQJ350WF2QWY106GWWZMGA4S','hearing-protection-hunters','published',NULL,NULL,'2026-05-01T15:40:08.975Z','2026-05-01T15:40:08.981Z','2026-05-01T15:40:08.975Z',NULL,NULL,1,'01KQJ350WPRVN4XB8Q4PEJ10B5',NULL,'en','01KQJ350WF2QWY106GWWZMGA4S','Hearing Protection for Hunters','Sudden, loud blasts from firearms can cause severe, permanent hearing damage. Our custom hunter''s ear protection provides incredible ambient sound awareness while protecting your hearing from dangerous impulse noise.','3');
INSERT OR IGNORE INTO [ec_pages] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[content]) VALUES ('01KQJ0K26C1MSAHHSCA7W501Y8','about','published',NULL,NULL,'2026-05-01T14:55:23.340Z','2026-05-01T14:55:23.340Z','2026-05-01T14:55:23.339Z',NULL,NULL,1,NULL,NULL,'en','01KQJ0K26C1MSAHHSCA7W501Y8','About','[{"_type":"block","style":"normal","children":[{"_type":"span","text":"A place for writing about software, design, and the occasional stray thought. No posting schedule, no newsletter funnel. Just things I wanted to write down."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"Built with Astro and EmDash. The source is open if you want to see how it works."}]}]');
INSERT OR IGNORE INTO [ec_posts] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[featured_image],[content],[excerpt]) VALUES ('01KQJ0K2DANMD6AHA1S0HPM47E','building-for-the-long-term','published',NULL,'01KQJ0K26A5HNWSKV0XEBCSK6A','2026-05-01T14:55:23.563Z','2026-05-01T14:55:23.563Z','2026-05-01T14:55:23.562Z',NULL,'2026-05-02T07:03:53.258Z',1,NULL,NULL,'en','01KQJ0K2DANMD6AHA1S0HPM47E','Building for the Long Term','{"provider":"local","id":"01KQJ0K2BBQBVR1Q58T8J1D920","alt":"Code on a monitor in a dark room","width":1200,"height":800,"mimeType":"image/jpeg","filename":"building-long-term.jpg","meta":{"storageKey":"01KQJ0K2BBQBVR1Q58T8J1D920.jpg"}}','[{"_type":"block","style":"normal","children":[{"_type":"span","text":"Every few years the industry collectively decides that everything we''ve been doing is wrong and there''s a better way. New frameworks, new paradigms, new build tools. The churn is relentless, and if you''re not careful, you spend more time migrating than building."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"I''ve been writing software long enough to have seen several of these cycles. jQuery to Backbone to Angular to React to whatever comes next. Each transition felt urgent at the time. Looking back, the things that actually mattered were rarely about the framework."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"What survives"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"Clean data models survive. Clear boundaries between systems survive. Good naming survives. The decision to keep things simple when you could have made them clever - that definitely survives."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"What doesn''t survive is code that was written to impress, abstractions built for problems that never materialized, and architectures designed around a framework''s opinions rather than the domain''s reality."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"The best code I''ve written is boring. It reads like prose, does one thing well, and doesn''t require a PhD in category theory to understand. The worst code I''ve written was technically impressive at the time."}]}]','The frameworks will change. The databases will change. What survives is the clarity of your thinking.');
INSERT OR IGNORE INTO [ec_posts] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[featured_image],[content],[excerpt]) VALUES ('01KQJ0K2E84HJ5GWN8YTDTMRAP','the-case-for-static','published',NULL,'01KQJ0K26A5HNWSKV0XEBCSK6A','2026-05-01T14:55:23.592Z','2026-05-01T14:55:23.592Z','2026-05-01T14:55:23.592Z',NULL,'2026-05-02T07:04:14.336Z',1,NULL,NULL,'en','01KQJ0K2E84HJ5GWN8YTDTMRAP','The Case for Static','{"provider":"local","id":"01KQJ0K2DVD57NXVC911HWR3P7","alt":"Laptop and coffee on a wooden table","width":1200,"height":800,"mimeType":"image/jpeg","filename":"case-for-static.jpg","meta":{"storageKey":"01KQJ0K2DVD57NXVC911HWR3P7.jpg"}}','[{"_type":"block","style":"normal","children":[{"_type":"span","text":"There''s a certain irony in the fact that the web started static, went dynamic, and is now swinging back toward static again. But the static sites of today aren''t the hand-coded HTML pages of 1998. They''re generated, optimized, and deployed to edge networks that serve them in milliseconds."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"The pitch for server-rendered everything was compelling: dynamic content, personalization, real-time data. But most sites don''t need most of that most of the time. A blog post doesn''t need to be rendered on every request. A product page doesn''t change every second."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"The performance argument"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"A static file served from a CDN is as fast as the web gets. No cold starts, no database queries, no server-side rendering overhead. The Time to First Byte is essentially the network latency to your nearest edge node. You can''t beat physics."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"And when you do need dynamic behavior, you can add it surgically. An island of interactivity in a sea of static HTML. The best of both worlds, without paying the cost of either at all times."}]}]','Static sites aren''t a step backwards. They''re what you get when you take performance and simplicity seriously.');
INSERT OR IGNORE INTO [ec_posts] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[featured_image],[content],[excerpt]) VALUES ('01KQJ0K2F20HRP7V5X7DCVWBX2','learning-in-public','published',NULL,NULL,'2026-05-01T14:55:23.619Z','2026-05-01T14:55:23.619Z','2026-05-01T14:55:23.618Z',NULL,'2026-05-02T07:04:16.440Z',1,NULL,NULL,'en','01KQJ0K2F20HRP7V5X7DCVWBX2','Learning in Public','{"provider":"local","id":"01KQJ0K2EPKF8ZZKAVNF2ZP31P","alt":"Notebook and pen on a desk","width":1200,"height":800,"mimeType":"image/jpeg","filename":"learning-in-public.jpg","meta":{"storageKey":"01KQJ0K2EPKF8ZZKAVNF2ZP31P.jpg"}}','[{"_type":"block","style":"normal","children":[{"_type":"span","text":"I started writing about things I was learning not because I had anything original to say, but because I kept forgetting what I''d figured out. The blog posts were notes to my future self, published publicly more out of laziness than courage."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"What I didn''t expect was how much the writing itself would accelerate the learning. There''s a particular kind of clarity that comes from trying to explain something to someone else. The gaps in your understanding, which you can happily ignore when the knowledge lives only in your head, become painfully obvious when you try to put it into sentences."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"The fear of being wrong"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"The biggest barrier isn''t time or writing skill. It''s the fear of publishing something that turns out to be wrong. But here''s the thing: being wrong publicly is one of the most efficient ways to learn. Someone will correct you, often kindly, and you''ll remember that correction forever."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"The posts that helped me most weren''t written by experts. They were written by people one step ahead of me on the same path, in language that hadn''t yet been polished into abstraction. There''s a place for that kind of writing, and it''s more valuable than most people realize."}]}]','Writing about what you''re learning is the fastest way to find out what you don''t actually understand.');
INSERT OR IGNORE INTO [ec_posts] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[featured_image],[content],[excerpt]) VALUES ('01KQJ0K2FN006K7KZ5G84JXGZ1','small-tools-big-impact','published',NULL,NULL,'2026-05-01T14:55:23.637Z','2026-05-01T14:55:23.637Z','2026-05-01T14:55:23.637Z',NULL,'2026-05-02T07:04:18.344Z',1,NULL,NULL,'en','01KQJ0K2FN006K7KZ5G84JXGZ1','Small Tools, Big Impact','{"provider":"local","id":"01KQJ0K2FHEX96H1Y4XFBPY83H","alt":"Wrenches and hand tools hanging on a workshop wall","width":1200,"height":800,"mimeType":"image/jpeg","filename":"small-tools.jpg","meta":{"storageKey":"01KQJ0K2FHEX96H1Y4XFBPY83H.jpg"}}','[{"_type":"block","style":"normal","children":[{"_type":"span","text":"There''s a class of software that doesn''t get enough appreciation. Not the frameworks or the platforms or the IDEs, but the small, sharp tools that solve one problem so well you stop thinking about them. They become invisible, which is the highest compliment you can pay a tool."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"I''m talking about things like ripgrep, which searches code so fast it changed how I think about searching. Or jq, which makes JSON feel like a first-class data format in the terminal. Or curl, which has been quietly powering the internet''s plumbing for decades."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"The Unix philosophy, revisited"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"Do one thing well. The advice is old enough to be a cliche, but the best modern tools still follow it. They don''t try to be platforms. They don''t have plugin ecosystems or configuration languages or startup wizards. They do their job and they compose with other tools that do theirs."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"The temptation is always to add more. One more feature, one more option, one more integration. But every addition is a decision someone has to make, a path through the code that has to be maintained, a thing that can break. The best tools resist this. They stay small, and in staying small, they stay reliable."}]}]','The best developer tools do one thing well and get out of your way. A love letter to focused software.');
INSERT OR IGNORE INTO [ec_posts] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[featured_image],[content],[excerpt]) VALUES ('01KQJ0K2GE41V53BEVYNRRZ2ZZ','designing-with-constraints','published',NULL,NULL,'2026-05-01T14:55:23.662Z','2026-05-01T14:55:23.662Z','2026-05-01T14:55:23.662Z',NULL,'2026-05-02T07:04:21.441Z',1,NULL,NULL,'en','01KQJ0K2GE41V53BEVYNRRZ2ZZ','Designing with Constraints','{"provider":"local","id":"01KQJ0K2GBE0QKQZEE9NNMBMG0","alt":"Pencils and design tools on a desk","width":1200,"height":800,"mimeType":"image/jpeg","filename":"designing-with-constraints.jpg","meta":{"storageKey":"01KQJ0K2GBE0QKQZEE9NNMBMG0.jpg"}}','[{"_type":"block","style":"normal","children":[{"_type":"span","text":"Give a designer a blank canvas and unlimited time, and they''ll often produce something mediocre. Give them a tight brief, a small screen, and a deadline, and they''ll surprise you. This isn''t a paradox - it''s how creativity actually works."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"Constraints force decisions. When you can''t use more than two typefaces, you have to choose carefully. When the page has to load in under a second, every element earns its place. When the interface has to work on a 320px screen, you discover what''s truly essential."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"Embracing the box"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"The web itself is a constraint. HTML flows in one direction. CSS has a box model. Browsers have viewport sizes and font rendering quirks. You can fight these constraints or you can work with them, and the results are dramatically different."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"The designs I admire most don''t look like they were forced through a framework. They look like they grew naturally from the medium, respecting its grain rather than working against it. That only happens when you treat constraints as creative partners rather than enemies."}]}]','Limitations aren''t obstacles to creativity. They''re the structure that makes creativity possible.');
INSERT OR IGNORE INTO [ec_posts] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[featured_image],[content],[excerpt]) VALUES ('01KQJ0K2H8V8FZ6C7E99H8M9QT','a-weekend-with-a-side-project','published',NULL,NULL,'2026-05-01T14:55:23.688Z','2026-05-01T14:55:23.688Z','2026-05-01T14:55:23.688Z',NULL,'2026-05-02T07:04:23.848Z',1,NULL,NULL,'en','01KQJ0K2H8V8FZ6C7E99H8M9QT','A Weekend with a Side Project','{"provider":"local","id":"01KQJ0K2H51K4VN6R2EWYJZ459","alt":"Code on a screen with a dark theme","width":1200,"height":800,"mimeType":"image/jpeg","filename":"weekend-side-project.jpg","meta":{"storageKey":"01KQJ0K2H51K4VN6R2EWYJZ459.jpg"}}','[{"_type":"block","style":"normal","children":[{"_type":"span","text":"Saturday morning. Coffee''s made, the house is quiet, and I''ve got an idea that''s been nagging at me all week. Not a good idea, necessarily - just a persistent one. A small tool that does a thing I keep doing manually. How hard could it be?"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"This is the best kind of programming. No requirements document, no sprint planning, no pull request reviews. Just a text editor and a problem. The freedom to make terrible architectural decisions, rewrite everything twice, and follow tangents that turn out to be dead ends."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"Why side projects matter"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"Side projects are where you learn things your day job would never teach you. Not because the problems are harder, but because you''re free to take risks. Try a language you''ve never used. Build something without a framework. Deploy to a platform you''ve only read about. The stakes are zero, which makes the learning maximum."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"By Sunday evening, the thing sort of works. It''s rough, the error handling is nonexistent, and the README is a single sentence. But it solves the problem I set out to solve, and I learned three things I didn''t know on Friday. Not a bad weekend."}]}]','No stakeholders, no deadlines, no Jira tickets. Just you and a dumb idea that might turn into something.');
INSERT OR IGNORE INTO [ec_posts] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[featured_image],[content],[excerpt]) VALUES ('01KQJ0K2HX6NQHE6H6WN2MMYKV','notes-on-simplicity','published',NULL,NULL,'2026-05-01T14:55:23.709Z','2026-05-01T14:55:23.709Z','2026-05-01T14:55:23.709Z',NULL,'2026-05-02T07:04:25.513Z',1,NULL,NULL,'en','01KQJ0K2HX6NQHE6H6WN2MMYKV','Notes on Simplicity','{"provider":"local","id":"01KQJ0K2HQ7MBS53W319M1Y2V4","alt":"Geometric pattern carved into white paper","width":1200,"height":800,"mimeType":"image/jpeg","filename":"notes-on-simplicity.jpg","meta":{"storageKey":"01KQJ0K2HQ7MBS53W319M1Y2V4.jpg"}}','[{"_type":"block","style":"normal","children":[{"_type":"span","text":"Every piece of software starts simple. A few files, a clear purpose, a small surface area. Then features get added, edge cases get handled, and before long you''re looking at something that requires a diagram to understand. This isn''t inevitable, but it takes discipline to prevent."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"The hard part of simplicity isn''t the initial design. It''s the ongoing resistance to complication. Every feature request, every bug fix, every refactor is an opportunity to add complexity. Saying no is the most important design skill, and the least celebrated."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"Removing as a feature"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"The best version of a product often has fewer features than the previous one. Not because features were missing, but because someone had the courage to remove things that weren''t earning their keep. Every feature has a cost - in maintenance, in cognitive load, in the weight of the interface."}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"Simplicity is a practice, not a destination. You never arrive at simple. You just keep asking: is this necessary? Could this be clearer? Is there a way to solve this problem by removing something instead of adding something? The answer is yes more often than you''d expect."}]}]','Simplicity isn''t the absence of complexity. It''s the result of understanding a problem well enough to solve it cleanly.');
INSERT OR IGNORE INTO [ec_posts] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[featured_image],[content],[excerpt]) VALUES ('01KQJ0K2HYHX790DAN86FS3MKZ','work-in-progress','draft',NULL,NULL,'2026-05-01T14:55:23.711Z','2026-05-01T14:55:23.711Z',NULL,NULL,'2026-05-02T07:04:27.504Z',1,NULL,NULL,'en','01KQJ0K2HYHX790DAN86FS3MKZ','Work in Progress',NULL,'[{"_type":"block","style":"normal","children":[{"_type":"span","text":"This is a draft post that won''t appear in the public listing."}]}]','This post is still being written.');
INSERT OR IGNORE INTO [ec_posts] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[featured_image],[content],[excerpt]) VALUES ('01KQJ3519HZEF5HSZPCHZ3JTX5','signs-you-need-hearing-test','published',NULL,'01KQJ350GH2645TE6QSSVNWSP5','2026-05-01T15:40:09.393Z','2026-05-01T15:40:09.444Z','2026-05-01T15:40:09.393Z',NULL,'2026-05-02T07:03:49.463Z',1,'01KQJ351B4NEVXM1Y0C6JD73X7',NULL,'en','01KQJ3519HZEF5HSZPCHZ3JTX5','5 Signs You May Need a Hearing Test',NULL,'[{"_type":"block","style":"normal","children":[{"_type":"span","text":"Hearing loss often develops so gradually that many people don''t notice it until it begins significantly affecting their daily life. Knowing the warning signs can help you seek care before the problem worsens."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"1. Asking people to repeat themselves"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"If you frequently ask friends, family, or coworkers to repeat what they''ve said, this is one of the most common early signs of hearing loss. It may be happening more than you realize."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"2. Difficulty hearing in noisy environments"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"Struggling to follow conversations in restaurants, social gatherings, or other noisy places is a hallmark sign of hearing difficulty. Background noise can be especially challenging for people with hearing loss."}]}]','Hearing loss often develops gradually. Here are the key signs to watch for and when to schedule your evaluation.');
INSERT OR IGNORE INTO [ec_posts] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[featured_image],[content],[excerpt]) VALUES ('01KQJ351DN14CXS7AKYAZSQR06','modern-hearing-aids-technology','published',NULL,'01KQJ350GH2645TE6QSSVNWSP5','2026-05-01T15:40:09.525Z','2026-05-01T15:40:09.531Z','2026-05-01T15:40:09.525Z',NULL,NULL,1,'01KQJ351DVDH9AN81AF2Q8ZJ77',NULL,'en','01KQJ351DN14CXS7AKYAZSQR06','How Modern Hearing Aid Technology Has Changed Lives',NULL,'[{"_type":"block","style":"normal","children":[{"_type":"span","text":"The hearing aids of today bear little resemblance to the bulky, whistling devices of decades past. Modern hearing aids are sleek, nearly invisible, and packed with technology that adapts to your environment in real time."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"Bluetooth connectivity"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"Most modern hearing aids can connect directly to smartphones, TVs, and other Bluetooth devices. This means you can stream phone calls, music, and audio directly to your hearing aids."}]}]','Today''s hearing aids are more advanced than ever — smaller, smarter, and connected. Here''s what you need to know.');
INSERT OR IGNORE INTO [ec_posts] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[featured_image],[content],[excerpt]) VALUES ('01KQJ351G09Z02G1N67A535JA1','tinnitus-causes-symptoms-treatment','published',NULL,'01KQJ350GH2645TE6QSSVNWSP5','2026-05-01T15:40:09.600Z','2026-05-01T15:40:09.602Z','2026-05-01T15:40:09.600Z',NULL,NULL,1,'01KQJ351G32SCDZ214VE28DK5R',NULL,'en','01KQJ351G09Z02G1N67A535JA1','Tinnitus: Causes, Symptoms, and Treatment Options',NULL,'[{"_type":"block","style":"normal","children":[{"_type":"span","text":"Tinnitus — the perception of ringing, buzzing, hissing, or other sounds in the ears — affects an estimated 50 million Americans. While it can be distressing, many effective management strategies are available."}]},{"_type":"block","style":"h2","children":[{"_type":"span","text":"Common causes of tinnitus"}]},{"_type":"block","style":"normal","children":[{"_type":"span","text":"Tinnitus can be caused by noise-induced hearing loss, age-related hearing loss, ear infections, earwax blockage, certain medications, or other medical conditions. Identifying the underlying cause is the first step to effective treatment."}]}]','Ringing in the ears affects millions of Americans. Learn what causes tinnitus and how it can be treated.');
INSERT OR IGNORE INTO [ec_services] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[description],[image],[link_url],[sort_order]) VALUES ('01KQJ350GPSVZ2Y02YX71CDAMJ','hearing-evaluations','published',NULL,NULL,'2026-05-01T15:40:08.599Z','2026-05-01T15:40:08.599Z','2026-05-01T15:40:08.598Z',NULL,NULL,1,'01KQJ350GQ3WPEY0TR76AVKQPD',NULL,'en','01KQJ350GPSVZ2Y02YX71CDAMJ','Hearing Evaluations','A comprehensive hearing evaluation is the first step toward better hearing. Our Doctor of Audiology will assess your hearing health using the latest diagnostic tools and techniques.',NULL,'/services','1');
INSERT OR IGNORE INTO [ec_services] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[description],[image],[link_url],[sort_order]) VALUES ('01KQJ350GR4MVYAX0Y2RQ0HJE3','hearing-loss-evaluation-treatment','published',NULL,NULL,'2026-05-01T15:40:08.600Z','2026-05-01T15:40:08.600Z','2026-05-01T15:40:08.600Z',NULL,NULL,1,'01KQJ350GRSMA0MV8VEQYF5WQM',NULL,'en','01KQJ350GR4MVYAX0Y2RQ0HJE3','Hearing Loss Evaluation & Treatment','We work together to understand what you are experiencing and recommend treatment options tailored to your specific type and degree of hearing loss with confidence.',NULL,'/services','2');
INSERT OR IGNORE INTO [ec_services] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[description],[image],[link_url],[sort_order]) VALUES ('01KQJ350GS985T25ZZ6TJ8G6Q7','ear-wax-removal','published',NULL,NULL,'2026-05-01T15:40:08.601Z','2026-05-01T15:40:08.602Z','2026-05-01T15:40:08.601Z',NULL,NULL,1,'01KQJ350GT87J4PTFED13MZRHF',NULL,'en','01KQJ350GS985T25ZZ6TJ8G6Q7','Ear Wax Removal','Excess earwax can sometimes accumulate and cause hearing loss. Our safe, professional ear wax removal services restore your hearing clarity quickly and comfortably.',NULL,'/services','3');
INSERT OR IGNORE INTO [ec_services] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[title],[description],[image],[link_url],[sort_order]) VALUES ('01KQJ350GV7VZ9S4ZW94JDGBK1','tinnitus-evaluations-treatment','published',NULL,NULL,'2026-05-01T15:40:08.603Z','2026-05-01T15:40:08.603Z','2026-05-01T15:40:08.603Z',NULL,NULL,1,'01KQJ350GVAA7K3F45DG6D3QEA',NULL,'en','01KQJ350GV7VZ9S4ZW94JDGBK1','Tinnitus Evaluations & Treatment','Ringing, buzzing, or whooshing in the ears can be stressful. We fully evaluate your tinnitus and discuss various treatment options designed to find what works best for you.',NULL,'/services','4');
INSERT OR IGNORE INTO [ec_site_config] ([id],[slug],[status],[author_id],[primary_byline_id],[created_at],[updated_at],[published_at],[scheduled_at],[deleted_at],[version],[live_revision_id],[draft_revision_id],[locale],[translation_group],[phone],[address_line1],[address_line2],[city_state],[email],[book_url],[hero_heading],[hero_subtext],[hero_image],[about_tagline],[about_heading],[about_text],[about_image],[team_heading],[team_text],[hours_mon],[hours_tue],[hours_wed],[hours_thu],[hours_fri],[hours_sat],[hours_sun],[map_embed_url],[services_heading],[services_subtext],[hearing_aids_heading],[hearing_aids_subtext],[protection_heading],[protection_subtext],[testimonials_heading],[faq_heading],[news_heading],[facebook_url],[instagram_url],[twitter_url],[footer_tagline]) VALUES ('01KQJ350GK9DQHMZYC30M6ZM54','main','published',NULL,NULL,'2026-05-01T15:40:08.595Z','2026-05-01T15:40:08.596Z','2026-05-01T15:40:08.594Z',NULL,NULL,1,'01KQJ350GM4HA1TJH2YK9A8ATG',NULL,'en','01KQJ350GK9DQHMZYC30M6ZM54','(844) 442-4222','201 Believe Lane, Suite B','','Georgetown, KY 40324','info@commonwealthaudiology.com','#book','Compassionate hearing care that feels like home.','Hearing care you can trust, for every stage of life.',NULL,'AUDIOLOGY EXCELLENCE & PATIENT CARE','Commonwealth Audiology','Life is full of meaningful sounds: laughter with loved ones, conversations with friends, music you love, and the world sounds all around you. When this changes, it can feel isolating, but we''re here to help. At Commonwealth Audiology, your hearing wellness is our top priority. Every recommendation we make is shaped by what functions for your specific lifestyle needs and the life you love to live. Our Doctor of Audiology, Dr. Tiffany Brown, stays up to date with the latest hearing technology to ensure you receive the most effective and innovative care available.',NULL,'Meet Your Local Hearing Professionals','At Commonwealth Audiology, our focus is on restoring clarity, comfort, and confidence so you can fully participate in the world around you. With superior guidance, clinical excellence, and care centered on you, we partner with our patients and their families each and every day.','9:00am - 5:00pm','9:00am - 5:00pm','9:00am - 5:00pm','9:00am - 5:00pm','9:00am - 5:00pm','9:00am - 1:00pm','Closed','https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3134!2d-84.5603!3d38.2098!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x0!2zMzjCsDEyJzM1LjMiTiA4NMKwMzMnMzcuMSJX!5e0!3m2!1sen!2sus!4v1234567890','Audiology Services in Georgetown, KY','At Commonwealth Audiology, we provide hearing care to meet your every need. It''s our commitment to make sure you can hear every moment clearly.','Hearing Aids & Hearing Aid Services','We provide best-in-class hearing aid solutions with expert fittings, adjustments, repairs, and ongoing maintenance so you can hear your best every day.','Hearing Protection Solutions in Georgetown, KY','For anyone exposed to loud noise, custom ear protection offers the safest and most comfortable way to preserve your hearing.','What Our Patients Are Saying','Frequently Asked Questions','News & Articles',NULL,NULL,NULL,'Compassionate hearing care in Georgetown, KY. Helping you hear every meaningful moment of life.');
